"""Synthetic two-second native ANT recordings at 1000 Hz, with no participant data."""
from collections.abc import Sequence
from pathlib import Path
import struct


def write_ant_fixture(path: Path, events: Sequence[tuple[str, int]], *, rf64: bool = True) -> Path:
    """Add an ordered native event chunk to a freshly written copy of a blank EEG.

    The two templates were generated by libeep 3.3.179's write_cnt and
    add_raw_samples (one Cz channel, 2000 zeros), with blank participant
    information and a fixed synthetic start date. Its RIFF evt rows contain
    a sample index and eight label bytes. Writing the rows directly lets us
    test duplicate markers at exactly the same sample without writer coalescing.
    """
    template = "zero-eeg-rf64.cnt" if rf64 else "zero-eeg-riff.cnt"
    data = (Path(__file__).with_name("ant_cnt") / template).read_bytes()
    size_format = "<Q" if rf64 else "<I"
    record = struct.Struct(size_format + "8s")
    payload = b"".join(record.pack(sample, code.encode("ascii")) for code, sample in events)
    chunk = b"evt " + struct.pack(size_format, len(payload)) + payload
    offset = 4 + struct.calcsize(size_format)
    header = data[:4] + struct.pack(size_format, len(data) - offset + len(chunk))
    with path.open("xb") as stream:
        stream.write(header + data[offset:] + chunk)
    return path
